-- Nine additional IPA-published 2023 FE A questions, matched by original question number to 2023 answer key.
-- Source: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf
-- Full textual context of tabular Q2 and functional-dependency Q6 retained; explanations newly authored.
-- INSERT OR IGNORE does not touch existing attempts or mastery.
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-02', 'exam-fe', 'データ構造', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問2】双方向ポインタをもつリストに社員 G を社員 A と社員 K の間へ追加する。追加前と比べて値が変わるポインタだけを選べ。

追加前：アドレス／社員名／次ポインタ／前ポインタ
100／社員A／300／0
200／社員T／0／300
300／社員K／200／100

追加後：アドレス／社員名／次ポインタ／前ポインタ
100／社員A／a／b
200／社員T／c／d
300／社員K／e／f
400／社員G／x／y', '[{"id":"a","text":"a，b，e，f"},{"id":"b","text":"a，e，f"},{"id":"c","text":"a，f"},{"id":"d","text":"b，e"}]', '"c"', 'GをAとKの間に挿入すると，Aの次ポインタaが300から400に，Kの前ポインタfが100から400に変わる。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-06', 'exam-fe', 'データベース', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問6】次の関数従属を満足するとき，成立する推移的関数従属はどれか。ここでA→BはBがAに関数従属することを表す。

{注文コード，商品コード} → {顧客注文数量，注文金額}
注文コード → {注文日，顧客コード，注文担当者コード}
商品コード → {商品名，仕入先コード，商品販売価格}
仕入先コード → {仕入先名，仕入先住所，仕入担当者コード}
顧客コード → {顧客名，顧客住所}', '[{"id":"a","text":"仕入先コード → 仕入担当者コード → 仕入先住所"},{"id":"b","text":"商品コード → 仕入先コード → 商品販売価格"},{"id":"c","text":"注文コード → 顧客コード → 顧客住所"},{"id":"d","text":"注文コード → 商品コード → 顧客注文数量"}]', '"c"', '注文コードから顧客コード，顧客コードから顧客住所が決まるので推移的関数従属が成立する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-09', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問9】ドライブバイダウンロード攻撃に該当するものはどれか。', '[{"id":"a","text":"PCからハードディスクを物理的に盗み，データをWebサイトで公開する。"},{"id":"b","text":"メール添付ファイルの実行によって感染し，ファイルを暗号化して復号用の身代金を要求する。"},{"id":"c","text":"利用者が悪意あるWebサイトにアクセスしたときに，Webブラウザの脆弱性を悪用してPCをマルウェアに感染させる。"},{"id":"d","text":"無料ソフトウェアに不正プログラムを混在させ，利用者にインストールさせる。"}]', '"c"', 'Webサイトを閲覧したことをきっかけにブラウザ等の脆弱性を突いてマルウェアをダウンロードさせる攻撃。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-14', 'exam-fe', 'システム監査', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問14】A社は自宅PCから社内ネットワークに接続するテレワークを計画し，情報セキュリティ管理基準に沿って運用規程を監査した。監査報告書の指摘事項とすべきものはどれか。', '[{"id":"a","text":"運用規程を守ることを条件に全従業員が利用できる。"},{"id":"b","text":"テレワークで使用するPCはA社支給のものに限定する。"},{"id":"c","text":"テレワークPCへのマルウェア対策ソフト導入の要不要を各従業員の判断に委ねる。"},{"id":"d","text":"テレワークPCを従業員の家族に使用させない。"}]', '"c"', 'マルウェア対策の要否を個人判断に委ねず，組織が統一したセキュリティ対策を定める必要がある。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-15', 'exam-fe', 'クラウド', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問15】ハイブリッドクラウドの説明はどれか。', '[{"id":"a","text":"クラウドサービスの一部機能を自社用にカスタマイズして使う。"},{"id":"b","text":"個人向けと企業向けの両方に同一のクラウドサービスを提供する。"},{"id":"c","text":"有料と無料のクラウドサービスに区分して提供する。"},{"id":"d","text":"自社専用クラウドと汎用クラウドの間でデータやアプリケーションを連携・相互運用できる環境を提供する。"}]', '"d"', 'プライベートクラウドとパブリッククラウドの組合せと連携を実現するのがハイブリッドクラウド。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-16', 'exam-fe', '経営・組織', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問16】ダイバーシティマネジメントの説明はどれか。', '[{"id":"a","text":"従業員が仕事と生活の調和を図り組織の活力を向上させる。"},{"id":"b","text":"性別，年齢，国籍など従業員の多様性を尊重し組織の活力を向上させる。"},{"id":"c","text":"従業員が自ら定めた目標に主体的に取り組み達成度に応じて評価する。"},{"id":"d","text":"労使が労働条件を合意し協調して収益増大を目指す。"}]', '"b"', '多様な背景・価値観の従業員を尊重し，組織の成果に活かす経営管理。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-17', 'exam-fe', '経営戦略', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問17】ERPを説明したものはどれか。', '[{"id":"a","text":"営業活動にITを活用して効率と顧客満足度を高める手法。"},{"id":"b","text":"卸売業者やメーカーが小売店の経営活動を支援する手法。"},{"id":"c","text":"企業全体の経営資源を総合的に計画・管理し，経営効率を高める手法。"},{"id":"d","text":"商取引をインターネットなど電子ネットワークで行う手法。"}]', '"c"', 'ERP（Enterprise Resource Planning）は企業全体の人・物・金などの経営資源を統合的に計画・管理する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-18', 'exam-fe', 'マーケティング', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問18】イノベータ理論で消費者を新製品の採用時期により五分類する。アーリーアダプタの説明として適切なものはどれか。', '[{"id":"a","text":"周囲の大多数が採用してから使う層。"},{"id":"b","text":"リスクを恐れず誰よりも早く採用する層。"},{"id":"c","text":"新製品を早期に採用し，流行に敏感で自ら調査・判断し他者にも影響を与える層。"},{"id":"d","text":"流行が一般化しても採用しない場合がある最も保守的な層。"}]', '"c"', 'アーリーアダプタは早期採用者であり，イノベータに続いて採用し他の消費者にも影響する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2023-a-20', 'exam-fe', '知的財産', 'standard', 'single_choice', '【2023年度 IPA公開問題 科目A 問20】ボリュームライセンス契約の説明はどれか。', '[{"id":"a","text":"企業などソフトウェア大量購入者向けにインストールできる台数を取り決めて使用を認める契約。"},{"id":"b","text":"使用場所だけを限定し施設内で人数や台数に制限なく使える契約。"},{"id":"c","text":"ダウンロード時に画面に表示される条件への同意で成立する契約。"},{"id":"d","text":"ソフトウェア包装を開いたことで一定の使用許諾契約が成立したとみなす契約。"}]', '"a"', '大量導入する企業向けにインストール台数などをまとめて許諾する契約がボリュームライセンス。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
